1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	
7	const BASE_PREMIUMS = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	  moonstone: 25,
14	} as const;
15	
16	// The six priced types are the domain, so they are derived from the premium
17	// table rather than restated: a type nobody prices cannot be insured. The
18	// unknown-type case (broomstick) is still a runtime error the tests will drive.
19	type ItemType = keyof typeof BASE_PREMIUMS;
20	
21	// Components (as opposed to main items) are the only things the block rule
22	// applies to, so the distinction has to be data, not a price coincidence.
23	// Typed as a set of ItemType so a component can never name an unpriced type.
24	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
25	
26	const PERCENT_WHOLE = 100;
27	
28	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
29	// floating-point error that shifts the spec's round-up in MHPCO's favour.
30	const percentOf = (percent: number, amount: number): number =>
31	  (amount * percent) / PERCENT_WHOLE;
32	
33	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
34	// round up, payouts (MHPCO pays) round down.
35	const roundPremiumInMHPCOsFavour = Math.ceil;
36	
37	export type ScenarioResult = { premium: number };
38	
39	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
40	// the surcharge and claim tests still to come). They are typed as optional so
41	// the scenarios the tests actually send typecheck, without pricing them.
42	type Item = {
43	  type: ItemType;
44	  material?: string;
45	  enchantment?: number;
46	  cursed?: boolean;
47	};
48	
49	type Step = { op: string; items: Item[] };
50	
51	// `customer` and `op` are likewise unread so far: the loyalty-discount and
52	// follow-up-contract tests will reach for them.
53	type Scenario = {
54	  customer: { yearsWithMHPCO: number };
55	  steps: Step[];
56	};
57	
58	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
59	
60	const sumBasePremiums = (items: Item[]): number =>
61	  items.reduce((total, item) => total + basePremiumForItem(item), 0);
62	
63	// Groups of items that are "alike" — same type. The type is kept alongside the
64	// items because the block rule asks about it; recovering it from items[0] would
65	// make every reader re-derive that a group is non-empty and homogeneous.
66	type AlikeItems = { type: ItemType; items: Item[] };
67	
68	const groupByType = (items: Item[]): AlikeItems[] => {
69	  const groups = new Map<ItemType, Item[]>();
70	  for (const item of items) {
71	    const group = groups.get(item.type) ?? [];
72	    group.push(item);
73	    groups.set(item.type, group);
74	  }
75	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
76	};
77	
78	// A block is a discount on the components' combined base premium, not a flat
79	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
80	// 20 % stays visible as the rule it is.
81	const blockBasePremium = (items: Item[]): number => {
82	  const undiscounted = sumBasePremiums(items);
83	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
84	};
85	
86	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
87	// pile is never cheaper than the block it contains. Components only — three
88	// swords are three separate insurances, not a discounted building block.
89	const formsABlock = ({ type, items }: AlikeItems): boolean =>
90	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
91	
92	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
93	  formsABlock(alikeItems)
94	    ? blockBasePremium(alikeItems.items)
95	    : sumBasePremiums(alikeItems.items);
96	
97	// Priced per group of alike items rather than over the whole list, so 3 runes
98	// and 3 moonstones each form their own block.
99	const policyBasePremiumFor = (items: Item[]): number =>
100	  groupByType(items)
101	    .map(basePremiumForGroup)
102	    .reduce((total, groupPremium) => total + groupPremium, 0);
103	
104	// Item-specific surcharges are charged on the affected item's own base premium
105	// and added alongside the policy base premium — never folded into it, or the
106	// policy-wide modifiers would compound on top of them.
107	const itemSurchargesFor = (items: Item[]): number =>
108	  items.reduce(
109	    (total, item) =>
110	      total + (item.cursed ? percentOf(CURSE_SURCHARGE_PERCENT, basePremiumForItem(item)) : 0),
111	    0,
112	  );
113	
114	const quoteFor = (items: Item[]): ScenarioResult => {
115	  const policyBasePremium = policyBasePremiumFor(items);
116	  const firstInsuranceSurcharge = percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
117	  const premium = roundPremiumInMHPCOsFavour(
118	    policyBasePremium + itemSurchargesFor(items) + firstInsuranceSurcharge + PROCESSING_FEE,
119	  );
120	  return { premium };
121	};
122	
123	// Every scenario so far holds exactly one quote step, so only the first is
124	// priced. The follow-up-contract discount test will drive priced-per-step.
125	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
126	  const [firstStep] = scenario.steps;
127	  return { results: [quoteFor(firstStep.items)] };
128	};
