// Each item-specific surcharge is a percentage of the affected item's OWN base
// premium, so the rule is expressed as that percentage and the condition that
// triggers it. Adding a rule means adding an entry here, not another branch.
const surchargeFor = (item: Item): number =>
  item.cursed ? percentOf(CURSE_SURCHARGE_PERCENT, basePremiumForItem(item)) : 0;

// Charged alongside the policy base premium — never folded into it, or the
// policy-wide modifiers would compound on top of them.
const itemSurchargesFor = (items: Item[]): number =>
  items.reduce((total, item) => total + surchargeFor(item), 0);
